(function() {
  'use strict';

  const state = {
    mode: 'sequence', // 'sequence' or 'token'
    k: 4,
    sequenceLength: 3
  };

  const els = {
    btnSeq: document.getElementById('mode-seq'),
    btnTok: document.getElementById('mode-tok'),
    statusLabel: document.getElementById('status-label'),
    dynamicLinks: document.getElementById('dynamic-links'),
    formulaContainer: document.getElementById('formula-container'),
    docItems: document.querySelectorAll('.doc-item')
  };

  const formulas = {
    sequence: "p(y|x) ≈ ∑<sub>z</sub> p(z|x) · ∏<sub>i=1</sub><sup>N</sup> p(y<sub>i</sub>|x, z, y<sub>1:i-1</sub>)",
    token: "p(y|x) ≈ ∏<sub>i=1</sub><sup>N</sup> [ ∑<sub>z</sub> p(z|x) · p(y<sub>i</sub>|x, z, y<sub>1:i-1</sub>) ]"
  };

  const descriptions = {
    sequence: "当前模式：全局文档承诺 (Global Commitment)",
    token: "当前模式：逐 Token 切换 (Per-Token Switching)"
  };

  function renderLinks() {
    els.dynamicLinks.innerHTML = '';
    const docsY = [120, 160, 200, 240]; // Relative to group transform
    const genX = 550;
    const genY = 200;
    const docGroupX = 360;

    if (state.mode === 'sequence') {
      // Sequence: One path from the "center of mass" of docs to generator
      // Visual metaphor: All docs merge into one probability stream
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      // Curve from middle of doc stack to generator
      const d = `M${docGroupX + 120},${200} C${docGroupX + 200},${200} ${genX - 50},${200} ${genX},${200}`;
      path.setAttribute('d', d);
      path.setAttribute('class', 'dynamic-link');
      path.setAttribute('stroke-width', '4');
      els.dynamicLinks.appendChild(path);

      // Highlight all docs equally as they contribute to the single sum
      els.docItems.forEach((item, i) => {
        const rect = item.querySelector('rect');
        rect.setAttribute('opacity', '0.6');
        rect.setAttribute('fill', 'var(--accent)');
      });

    } else {
      // Token: Multiple paths, representing independent sums for each token step
      // Visual metaphor: Parallel processing streams
      const colors = ['#2c5282', '#2b6cb0', '#3182ce'];

      for (let t = 0; t < state.sequenceLength; t++) {
        const yOffset = (t - 1) * 40;
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        // From doc stack to generator, slightly offset vertically to show parallelism
        const d = `M${docGroupX + 120},${200 + yOffset} C${docGroupX + 200},${200 + yOffset} ${genX - 50},${200 + yOffset} ${genX},${200 + yOffset}`;
        path.setAttribute('d', d);
        path.setAttribute('class', 'dynamic-link');
        path.setAttribute('stroke', colors[t % colors.length]);
        path.setAttribute('stroke-width', '2');
        els.dynamicLinks.appendChild(path);
      }

      // Highlight docs differently to imply selection per token
      els.docItems.forEach((item, i) => {
        const rect = item.querySelector('rect');
        rect.setAttribute('opacity', '0.4');
        rect.setAttribute('fill', 'var(--line)');
      });
    }
  }

  function updateFormula() {
    els.formulaContainer.innerHTML = `<div>${formulas[state.mode]}</div>`;
    els.statusLabel.textContent = descriptions[state.mode];
  }

  function setMode(mode) {
    state.mode = mode;
    if (mode === 'sequence') {
      els.btnSeq.classList.add('active');
      els.btnSeq.setAttribute('aria-pressed', 'true');
      els.btnTok.classList.remove('active');
      els.btnTok.setAttribute('aria-pressed', 'false');
    } else {
      els.btnTok.classList.add('active');
      els.btnTok.setAttribute('aria-pressed', 'true');
      els.btnSeq.classList.remove('active');
      els.btnSeq.setAttribute('aria-pressed', 'false');
    }
    renderLinks();
    updateFormula();
  }

  // Event Listeners
  els.btnSeq.addEventListener('click', () => setMode('sequence'));
  els.btnTok.addEventListener('click', () => setMode('token'));

  // Source Buttons Logic
  document.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const sourceId = e.target.getAttribute('data-source');
      // Dispatch custom event for the host to handle source viewing
      const event = new CustomEvent('papermind-source-request', {
        bubbles: true,
        detail: { sourceId: sourceId }
      });
      e.target.dispatchEvent(event);
    });
  });

  // Initialize
  setMode('sequence');

})();
